      SUBROUTINE RESET(I)CC     INITIALIZE COORDINATE TRANSFORMATION MATRICESCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'OC.CIN'      INCLUDE 'OCP.CIN'C      IMAX = I + 8      DO 1 J = I, IMAX, 4    1 X0L(J) = 0.0      IMIN = I + 4      IMAX = I + 28      DO 2 J = IMIN, IMAX, 4    2 OL(J) = 0.0      IMAX = I + 32      DO 3 J = I, IMAX, 16    3 OL(J) = 1.0      OCP(I) = .FALSE.      RETURN      END